(function(root){
 'use strict';
 const START='2026-10-01', END='2027-12-31', CYCLE_START='2026-10-05';
 const SHIFTS=[{id:0,name:'Ca 1',start:8,end:16,hours:8,time:'08:00 – 16:00'},{id:1,name:'Ca 2',start:16,end:24,hours:8,time:'16:00 – 00:00'},{id:2,name:'Ca 3',start:0,end:4,hours:4,time:'00:00 – 04:00'},{id:3,name:'Ca 4',start:4,end:8,hours:4,time:'04:00 – 08:00'}];
 const CYCLE=[0,1,1,0,2,2,3,3];
 const PATTERN28=[[0,1,2,3],[2,1,3,0],[2,0,3,1],[3,2,0,1],[3,2,1,0],[0,3,1,2],[0,2,1,3],[2,3,1,0],[3,0,1,2],[3,1,0,2],[0,1,2,3],[1,0,2,3],[1,3,2,0],[1,3,2,0],[1,0,3,2],[1,2,0,3],[0,2,1,3],[2,3,1,0],[2,3,0,1],[3,0,2,1],[2,0,3,1],[3,2,0,1],[0,2,3,1],[1,3,2,0],[1,0,3,2],[0,1,3,2],[2,1,0,3],[3,1,0,2]];
 const PREFIX4=[[0,1,2,3],[1,0,2,3],[0,1,3,2],[1,0,3,2]];
 const TAIL5=[[2,0,1,3],[2,3,1,0],[3,2,1,0],[2,3,0,1],[3,2,0,1]];
 const iso=d=>new Date(d).toISOString().slice(0,10);
 const add=(d,n)=>iso(Date.parse(d+'T00:00:00Z')+n*86400000);
 const diff=(a,b)=>Math.round((Date.parse(a+'T00:00:00Z')-Date.parse(b+'T00:00:00Z'))/86400000);
 const dates=[]; for(let d=START;d<=END;d=add(d,1))dates.push(d);
 function create(phases=[0,3,1,2,4,5,6,7]){return dates.map((date,i)=>({date,shifts:phases.map(p=>(i<4?PREFIX4[i]:i<452?PATTERN28[(i-4)%28]:TAIL5[i-452])[CYCLE[p]])}));}
 function validate(rows){
  const errors=[];
  if(!Array.isArray(rows)||rows.length!==dates.length)return ['Lịch phải đủ 457 ngày từ 01/10/2026 đến 31/12/2027.'];
  rows.forEach((row,i)=>{
   if(row.date!==dates[i])errors.push('Ngày sai hoặc thiếu tại dòng '+(i+1));
   if(!Array.isArray(row.shifts)||row.shifts.length!==8||row.shifts.some(s=>!Number.isInteger(s)||s<0||s>3)){errors.push('Dữ liệu ca không hợp lệ ngày '+dates[i]);return;}
   for(let s=0;s<4;s++)if(row.shifts.filter(x=>x===s).length!==2)errors.push(dates[i]+': '+SHIFTS[s].name+' phải có 2 người.');
   if(i&&Array.isArray(rows[i-1].shifts))row.shifts.forEach((s,e)=>{const prev=SHIFTS[rows[i-1].shifts[e]];if(!prev)return;const rest=24+SHIFTS[s].start-prev.end;if(rest<8||rest>24)errors.push(dates[i]+': nhân viên '+(e+1)+' nghỉ '+rest+' giờ.');});
  });
  if(!errors.length)for(let i=4;i+28<=rows.length;i+=28){
   stats(rows.slice(i,i+28)).forEach((st,e)=>{if(st.counts[0]+st.counts[1]!==14)errors.push('Chu kỳ '+((i-4)/28+1)+': nhân viên '+(e+1)+' cần đúng 14 ca ngày và 14 ca đêm.');});
  }
  return errors;
 }
 function stats(rows){return Array.from({length:8},(_,e)=>{const counts=[0,0,0,0];rows.forEach(r=>counts[r.shifts[e]]++);return {counts,hours:counts.reduce((n,c,s)=>n+c*SHIFTS[s].hours,0),days:rows.length};});}
 function phasesFor(choices){const used=new Set();return choices.map(s=>{const p=CYCLE.findIndex((v,i)=>v===Number(s)&&!used.has(i));if(p<0)throw Error('Mỗi ca khởi đầu phải có đúng 2 nhân viên.');used.add(p);return p;});}
 function swapWindow(date){const i=diff(date,START);if(!dates.includes(date))throw Error('Ngày đổi ca nằm ngoài kỳ.');const begin=i<4?0:i>=452?452:4+Math.floor((i-4)/28)*28;return {start:dates[begin],end:dates[Math.min(begin+(begin===0?4:begin===452?5:28)-1,456)]};}
 function swapBundle(rows,first,compensation=null){
  const {date,a,b}=first,window=swapWindow(date);
  if(!Number.isInteger(a)||!Number.isInteger(b)||a<0||a>7||b<0||b>7||a===b)throw Error('Chọn hai nhân viên khác nhau.');
  const i=diff(date,START),sa=rows[i].shifts[a],sb=rows[i].shifts[b];
  if(sa===sb)throw Error('Hai nhân viên đang cùng ca, không cần đổi.');
  const indices=[i];
  if(compensation){
   if(compensation===date)throw Error('Hai lần đổi phải ở hai ngày khác nhau.');
   if(!dates.includes(compensation)||compensation<window.start||compensation>window.end)throw Error('Ngày đổi bù phải nằm trong cùng chu kỳ 4 tuần (hoặc cùng phần ngày lẻ).');
   const j=diff(compensation,START),ta=rows[j].shifts[a],tb=rows[j].shifts[b];
   if((sa<2)===(sb<2)||(ta<2)!==(sb<2)||(tb<2)!==(sa<2))throw Error('Lần đổi bù phải đổi ca ngày ↔ ca đêm theo chiều ngược lại cho cùng hai người.');
   indices.push(j);
  }
  return rows.map((r,k)=>{if(!indices.includes(k))return r;const shifts=r.shifts.slice();[shifts[a],shifts[b]]=[shifts[b],shifts[a]];return {date:r.date,shifts};});
 }
 function compensationDates(rows,first){const window=swapWindow(first.date);return rows.filter(r=>r.date>=window.start&&r.date<=window.end&&r.date!==first.date).filter(r=>{try{return !validate(swapBundle(rows,first,r.date)).length;}catch{return false;}}).map(r=>r.date);}
 const api={START,END,CYCLE_START,SHIFTS,CYCLE,dates,add,diff,create,validate,stats,phasesFor,swapWindow,swapBundle,compensationDates};
 if(typeof module!=='undefined'&&module.exports)module.exports=api;else root.PageScheduler=api;
})(typeof globalThis!=='undefined'?globalThis:this);

const APP_HTML="<!doctype html>\n<html lang=\"vi\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>PageOps · Quản lý ca trực</title>\n<style>\n:root{--ink:#16352d;--muted:#657b73;--green:#14785d;--bg:#f4f7f4;--line:#dce6df}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font:15px/1.5 'Segoe UI',Arial,sans-serif}button,input,select{font:inherit}button{cursor:pointer;border:1px solid var(--line);border-radius:9px;padding:9px 14px;background:white;color:var(--ink)}button:hover{background:#eaf3ed}button.primary{background:var(--green);color:white;border-color:var(--green)}input,select{padding:9px;border:1px solid var(--line);border-radius:8px;background:white;color:var(--ink)}header{background:#153e33;color:white;padding:23px 4%;display:flex;justify-content:space-between;align-items:center}.brand{font-size:23px;font-weight:750;letter-spacing:-1px}.brand span{color:#9bdbc0}header small{color:#b9d0c6}.shell{max-width:1500px;margin:auto;padding:30px 4%}h1{font-size:30px;letter-spacing:-.8px;margin:0}h2{font-size:19px;margin:0}p{margin:8px 0;color:var(--muted)}.intro{display:flex;justify-content:space-between;gap:20px;align-items:center;margin-bottom:25px}.badge{background:#e3f1e8;color:#176140;border:1px solid #c4dfcd;border-radius:20px;padding:7px 13px;white-space:nowrap}.cards{display:grid;grid-template-columns:repeat(4,1fr);gap:16px;margin:20px 0}.card,.panel{background:white;border:1px solid var(--line);border-radius:14px}.card{padding:18px}.card small{color:var(--muted)}.metric{font-size:28px;font-weight:700;margin:6px 0}.metric span{font-size:13px;font-weight:400;color:var(--muted)}.panel{padding:22px;margin:20px 0}.toolbar{display:flex;align-items:center;justify-content:space-between;gap:12px;flex-wrap:wrap}.controls{display:flex;align-items:center;gap:8px;flex-wrap:wrap}.legend{display:flex;gap:16px;flex-wrap:wrap;margin:18px 0;font-size:13px}.dot{display:inline-block;width:9px;height:9px;border-radius:50%;margin-right:6px}.s0{background:#e6f2e9;color:#26623e}.s1{background:#e5edff;color:#3654a3}.s2{background:#eee8fa;color:#72519e}.s3{background:#fff0dc;color:#a16b20}.dot.s0{background:#529570}.dot.s1{background:#738bc3}.dot.s2{background:#9d7aba}.dot.s3{background:#d5a55e}.scroll{overflow:auto}table{border-collapse:collapse;width:100%;text-align:left;white-space:nowrap}th{font-size:12px;font-weight:600;color:var(--muted);padding:14px 9px;background:#f7faf7;border-bottom:1px solid var(--line)}td{padding:12px 9px;border-bottom:1px solid #eef2ee}.name{font-weight:650;min-width:110px}.shift{width:100%;padding:9px 7px;border:0;font-size:13px;font-weight:600;border-radius:7px}.hours{font-weight:700}.foot{font-size:12px;color:var(--muted);margin-top:13px}.notice{background:#fff7e9;border:1px solid #e8d9b9;border-radius:11px;padding:14px 17px;font-size:14px;color:#775921;margin-top:18px}.twocol{display:grid;grid-template-columns:1.1fr 1fr;gap:20px}.twocol .panel{margin:0}.settings{display:grid;grid-template-columns:repeat(2,1fr);gap:10px;margin:17px 0}.person{display:flex;gap:6px}.person input{width:80px;flex:1;min-width:40px}.person select{width:100px}.status{font-size:13px;color:#37764b}footer{font-size:12px;color:var(--muted);padding:20px 0}dialog{border:1px solid var(--line);border-radius:15px;padding:25px;max-width:460px;width:90%;color:var(--ink)}dialog::backdrop{background:#153e3370}dialog label{display:block;margin:15px 0 5px}.danger{color:#ae4031}#toast{position:fixed;bottom:24px;left:50%;transform:translateX(-50%);background:#173c30;color:white;padding:13px 22px;border-radius:10px;box-shadow:0 6px 30px #0003;display:none;max-width:90%;z-index:5}details summary{cursor:pointer;font-weight:600}details p{font-size:14px}.progress{height:7px;background:#edf2ed;border-radius:5px;margin-top:7px}.progress div{height:100%;background:#4c9677;border-radius:5px}@media(max-width:900px){.cards{grid-template-columns:repeat(2,1fr)}.twocol{grid-template-columns:1fr}.intro{align-items:flex-start;flex-direction:column}.shell{padding:20px 4%}.panel{padding:15px}}@media print{header{color:black;background:white}.controls,.settings,button,.twocol,footer,.foot{display:none!important}.shell{padding:0}.panel{border:0;padding:0}.cards{gap:5px}.card{padding:8px}.shift{border:1px solid #ddd}.notice{background:white}.scroll{overflow:visible}h1{font-size:22px}body{font-size:11px}}\n</style></head><body>\n<header><div class=\"brand\">Page<span>Ops</span> <small style=\"font-size:12px;letter-spacing:0;margin-left:16px\">QUẢN LÝ NHÂN SỰ TRỰC PAGE</small></div><div class=\"controls\"><small id=\"accessRole\"></small><button id=\"logout\">Đăng xuất</button></div></header>\n<main class=\"shell\"><div class=\"intro\"><div><h1>Lịch trực, rõ ràng mỗi ngày.</h1><p>8 nhân viên · 4 ca · 2 người mỗi ca · Luân phiên theo chu kỳ 4 tuần</p></div><div class=\"badge\" id=\"health\">Đang kiểm tra lịch</div></div>\n<div class=\"cards\"><div class=\"card\"><small>NHÂN SỰ / NGÀY</small><div class=\"metric\">8 <span>người · mỗi người 1 ca</span></div><small>Phủ đủ 24 giờ trực page</small></div><div class=\"card\"><small>GIỜ TRONG CHU KỲ GỐC</small><div class=\"metric\">168 <span>giờ / người / 4 tuần</span></div><small>14 ca ngày · 14 ca đêm / người</small></div><div class=\"card\"><small>KHOẢNG NGHỈ THỰC TẾ</small><div class=\"metric\" id=\"restMetric\">8–24 <span>giờ</span></div><small>Kiểm tra cả ranh giới tuần và tháng</small></div><div class=\"card\"><small>CHÊNH LỆCH TOÀN KỲ</small><div class=\"metric\" id=\"gapMetric\"></div><small id=\"totalRange\"></small></div></div>\n<section class=\"panel\"><div class=\"toolbar\"><div><h2 id=\"weekTitle\">Lịch tuần</h2><p style=\"font-size:13px;margin-bottom:0\">Bấm vào ca để đổi với đồng nghiệp. Có thể chọn hai lần đổi bù và lưu cùng lúc.</p></div><div class=\"controls\"><button id=\"prev\" aria-label=\"Tuần trước\">←</button><input id=\"date\" type=\"date\" min=\"2026-10-01\" max=\"2027-12-31\" value=\"2026-10-05\" aria-label=\"Chọn ngày\"><button id=\"next\" aria-label=\"Tuần sau\">→</button><button id=\"print\">In tuần</button><button id=\"csv\" class=\"primary\">Xuất CSV</button></div></div>\n<div class=\"legend\" id=\"legend\"></div><div class=\"scroll\"><table id=\"weekTable\"></table></div><div class=\"foot\" id=\"weekFoot\"></div>\n<div class=\"notice\">Giờ làm bằng nhau tuyệt đối theo từng tuần là không thể với cơ cấu ca hiện tại: 48 giờ công/ngày ÷ 8 người × 7 ngày = 42 giờ/người, trong khi mọi ca đều là bội số của 4 giờ. Lịch gốc luân phiên theo 4 tuần: mỗi người có hai tuần 40 giờ, hai tuần 44 giờ; tổng 168 giờ, gồm 14 ca ngày và 14 ca đêm.</div></section>\n<div class=\"twocol\"><section class=\"panel\" id=\"setupPanel\"><div class=\"toolbar\"><h2>Nhân viên & ca khởi đầu</h2><span class=\"status\">Ngày 01/10/2026</span></div><p style=\"font-size:13px\">Chọn ca cho mỗi người ở ngày đầu tiên, đúng 2 người/ca. Các ngày tiếp theo tự luân phiên để giữ khoảng nghỉ.</p><div class=\"settings\" id=\"settings\"></div><div class=\"controls\"><button id=\"rename\">Lưu tên</button><button id=\"regenerate\" class=\"primary\">Tạo lại lịch theo lựa chọn</button></div><p class=\"foot\">Tạo lại lịch sẽ thay thế các lần đổi ca trong toàn kỳ. Tải bản sao JSON trước khi thay thế nếu cần giữ lịch cũ.</p></section>\n<section class=\"panel\"><div class=\"toolbar\"><h2>Thống kê giờ làm</h2><select id=\"scope\" aria-label=\"Phạm vi thống kê\"><option value=\"all\">Toàn kỳ · 457 ngày</option><option value=\"month\">Tháng đang xem</option><option value=\"week\">Tuần đang xem</option><option value=\"cycle\">Chu kỳ 4 tuần đang xem</option></select></div><div class=\"scroll\"><table id=\"stats\"></table></div><p class=\"foot\" id=\"statNote\"></p></section></div>\n<section class=\"panel\"><div class=\"toolbar\"><div><h2>Dữ liệu & bản sao</h2><p style=\"font-size:13px\">Lịch lưu trên máy chủ và đồng bộ cho mọi nhân viên. Dùng JSON để sao lưu hoặc nhập lịch cũ.</p></div><div class=\"controls\"><button id=\"backup\">Tải bản sao JSON</button><button id=\"import\">Nhập bản sao</button><input type=\"file\" id=\"file\" accept=\".json,application/json\" hidden></div></div><details style=\"margin-top:14px\"><summary>Quy tắc xếp ca và cách sử dụng</summary><p>Ca 2 kết thúc lúc 00:00 của ngày tiếp theo. Ca 3 và ca 4 thuộc ngày bắt đầu ghi trên lịch. Khoảng nghỉ tính từ lúc kết thúc ca trước đến lúc bắt đầu ca tiếp theo, theo thời gian Việt Nam.</p><p>Chu kỳ gốc dài 28 ngày. Mỗi người làm 7 lần mỗi ca: 14 ca ngày (ca 1–2) và 14 ca đêm (ca 3–4), tổng 168 giờ. Hai nhóm luân phiên tuần 40 giờ và tuần 44 giờ. Mỗi ngày luôn đủ 2 người/ca. Tất cả đều làm mỗi ngày, chưa có ngày nghỉ phép hoặc nghỉ tuần.</p><p>Toàn kỳ có 457 ngày, gồm 4 ngày đầu kỳ, 16 chu kỳ 28 ngày và 5 ngày cuối kỳ. Lịch gốc có 4 người làm 2.740 giờ và 4 người làm 2.744 giờ. Không thể chia đúng 2.742 giờ/người vì ca là bội số của 4 giờ. Đổi ca chỉ được chấp nhận khi vẫn có 14 ca ngày và 14 ca đêm/người trong từng chu kỳ 28 ngày đầy đủ. Khi đổi ngày ↔ đêm, chọn “Đổi hai lần bù nhau”; ứng dụng gợi ý ngày đổi ngược lại với cùng đồng nghiệp trong cùng chu kỳ. Cả hai lần được kiểm tra và lưu cùng lúc; nếu không có ngày hợp lệ, hãy chọn cặp nhân viên hoặc ngày đầu khác. Phần ngày lẻ đầu/cuối kỳ chỉ cho đổi bù trong cùng phần ngày lẻ.</p><p>Ứng dụng kiểm tra mọi ngày và mọi khoảng nghỉ trong kỳ, kể cả sau đổi ca hoặc nhập dữ liệu. Tuần bắt đầu từ thứ Hai và kết thúc Chủ nhật. Chu kỳ 4 tuần đầy đủ đầu tiên là 05/10–01/11/2026; cứ đủ 28 ngày thì lặp lại. Các ngày 01–04/10/2026 và 27–31/12/2027 được xếp riêng để toàn kỳ chỉ lệch 4 giờ. Chưa kiểm tra ca trước 01/10/2026 và sau 31/12/2027 vì không có dữ liệu. “Chọn ca” ở đây là chọn ca khởi đầu; giữ cố định ca cả kỳ sẽ không cân bằng giờ giữa ca 8 giờ và ca 4 giờ.</p><p>Nhân viên đăng nhập bằng mật khẩu xem lịch. Người quản lý dùng mật khẩu riêng để sửa; thay đổi được lưu trên máy chủ. Trang tự kiểm tra lịch mới mỗi 15 giây. Xuất CSV để mở trong Excel. Xuất CSV toàn kỳ theo ngày và nhân viên, gồm giờ bắt đầu, kết thúc, giờ công và khoảng nghỉ.</p></details></section>\n<footer>PageOps · Lịch dùng chung · <span id=\"saveStatus\">Đang kết nối máy chủ…</span></footer><section class=\"panel\" id=\"adminPanel\" hidden><h2>Quản trị truy cập</h2><p>Mật khẩu nhân viên chỉ cho phép xem. Mật khẩu quản lý cho phép sửa lịch.</p><form id=\"passwordForm\"><div class=\"controls\"><select id=\"passwordRole\" aria-label=\"Đổi mật khẩu cho\"><option value=\"viewer\">Mật khẩu nhân viên</option><option value=\"admin\">Mật khẩu quản lý</option></select><input id=\"currentPassword\" type=\"password\" autocomplete=\"current-password\" required placeholder=\"Mật khẩu quản lý hiện tại\" aria-label=\"Mật khẩu quản lý hiện tại\"><input id=\"newPassword\" type=\"password\" autocomplete=\"new-password\" required maxlength=\"200\" placeholder=\"Mật khẩu mới\" aria-label=\"Mật khẩu mới\"><button type=\"submit\">Đổi mật khẩu</button></div><p class=\"foot\">Nhân viên: ít nhất 8 ký tự. Quản lý: ít nhất 12 ký tự. Đổi mật khẩu sẽ đăng xuất các phiên khác của vai trò đó.</p></form><h2 style=\"margin-top:22px\">Lịch sử cập nhật</h2><div class=\"scroll\"><table id=\"historyTable\"></table></div></section></main>\n<dialog id=\"swapDialog\"><h2 id=\"swapTitle\">Đổi ca</h2><p id=\"swapInfo\"></p><label for=\"partner\">Đổi với nhân viên</label><select id=\"partner\" style=\"width:100%\"></select><label for=\"swapMode\">Cách đổi ca</label><select id=\"swapMode\" style=\"width:100%\"><option value=\"single\">Đổi một lần</option><option value=\"paired\">Đổi hai lần bù nhau</option></select><div id=\"compensationFields\" hidden><label for=\"compensation\">Ngày đổi bù với cùng nhân viên</label><select id=\"compensation\" style=\"width:100%\"></select><p class=\"foot\" id=\"compensationNote\"></p></div><p id=\"swapPreview\" style=\"white-space:pre-line\"></p><p class=\"danger\" id=\"swapError\"></p><div class=\"controls\" style=\"justify-content:flex-end;margin-top:20px\"><button id=\"cancelSwap\">Hủy</button><button id=\"applySwap\" class=\"primary\">Áp dụng đổi ca</button></div></dialog>\n<dialog id=\"confirmDialog\"><h2>Tạo lại toàn bộ lịch?</h2><p>Các lần đổi ca hiện tại sẽ được thay bằng lịch luân phiên theo lựa chọn ca khởi đầu.</p><div class=\"controls\" style=\"margin-top:20px\"><button id=\"cancelReset\">Hủy</button><button id=\"confirmReset\" class=\"primary\">Tạo lại lịch</button></div></dialog><div id=\"toast\" role=\"status\"></div>\n<script>\n(function(root){\n 'use strict';\n const START='2026-10-01', END='2027-12-31', CYCLE_START='2026-10-05';\n const SHIFTS=[{id:0,name:'Ca 1',start:8,end:16,hours:8,time:'08:00 – 16:00'},{id:1,name:'Ca 2',start:16,end:24,hours:8,time:'16:00 – 00:00'},{id:2,name:'Ca 3',start:0,end:4,hours:4,time:'00:00 – 04:00'},{id:3,name:'Ca 4',start:4,end:8,hours:4,time:'04:00 – 08:00'}];\n const CYCLE=[0,1,1,0,2,2,3,3];\n const PATTERN28=[[0,1,2,3],[2,1,3,0],[2,0,3,1],[3,2,0,1],[3,2,1,0],[0,3,1,2],[0,2,1,3],[2,3,1,0],[3,0,1,2],[3,1,0,2],[0,1,2,3],[1,0,2,3],[1,3,2,0],[1,3,2,0],[1,0,3,2],[1,2,0,3],[0,2,1,3],[2,3,1,0],[2,3,0,1],[3,0,2,1],[2,0,3,1],[3,2,0,1],[0,2,3,1],[1,3,2,0],[1,0,3,2],[0,1,3,2],[2,1,0,3],[3,1,0,2]];\n const PREFIX4=[[0,1,2,3],[1,0,2,3],[0,1,3,2],[1,0,3,2]];\n const TAIL5=[[2,0,1,3],[2,3,1,0],[3,2,1,0],[2,3,0,1],[3,2,0,1]];\n const iso=d=>new Date(d).toISOString().slice(0,10);\n const add=(d,n)=>iso(Date.parse(d+'T00:00:00Z')+n*86400000);\n const diff=(a,b)=>Math.round((Date.parse(a+'T00:00:00Z')-Date.parse(b+'T00:00:00Z'))/86400000);\n const dates=[]; for(let d=START;d<=END;d=add(d,1))dates.push(d);\n function create(phases=[0,3,1,2,4,5,6,7]){return dates.map((date,i)=>({date,shifts:phases.map(p=>(i<4?PREFIX4[i]:i<452?PATTERN28[(i-4)%28]:TAIL5[i-452])[CYCLE[p]])}));}\n function validate(rows){\n  const errors=[];\n  if(!Array.isArray(rows)||rows.length!==dates.length)return ['Lịch phải đủ 457 ngày từ 01/10/2026 đến 31/12/2027.'];\n  rows.forEach((row,i)=>{\n   if(row.date!==dates[i])errors.push('Ngày sai hoặc thiếu tại dòng '+(i+1));\n   if(!Array.isArray(row.shifts)||row.shifts.length!==8||row.shifts.some(s=>!Number.isInteger(s)||s<0||s>3)){errors.push('Dữ liệu ca không hợp lệ ngày '+dates[i]);return;}\n   for(let s=0;s<4;s++)if(row.shifts.filter(x=>x===s).length!==2)errors.push(dates[i]+': '+SHIFTS[s].name+' phải có 2 người.');\n   if(i&&Array.isArray(rows[i-1].shifts))row.shifts.forEach((s,e)=>{const prev=SHIFTS[rows[i-1].shifts[e]];if(!prev)return;const rest=24+SHIFTS[s].start-prev.end;if(rest<8||rest>24)errors.push(dates[i]+': nhân viên '+(e+1)+' nghỉ '+rest+' giờ.');});\n  });\n  if(!errors.length)for(let i=4;i+28<=rows.length;i+=28){\n   stats(rows.slice(i,i+28)).forEach((st,e)=>{if(st.counts[0]+st.counts[1]!==14)errors.push('Chu kỳ '+((i-4)/28+1)+': nhân viên '+(e+1)+' cần đúng 14 ca ngày và 14 ca đêm.');});\n  }\n  return errors;\n }\n function stats(rows){return Array.from({length:8},(_,e)=>{const counts=[0,0,0,0];rows.forEach(r=>counts[r.shifts[e]]++);return {counts,hours:counts.reduce((n,c,s)=>n+c*SHIFTS[s].hours,0),days:rows.length};});}\n function phasesFor(choices){const used=new Set();return choices.map(s=>{const p=CYCLE.findIndex((v,i)=>v===Number(s)&&!used.has(i));if(p<0)throw Error('Mỗi ca khởi đầu phải có đúng 2 nhân viên.');used.add(p);return p;});}\n function swapWindow(date){const i=diff(date,START);if(!dates.includes(date))throw Error('Ngày đổi ca nằm ngoài kỳ.');const begin=i<4?0:i>=452?452:4+Math.floor((i-4)/28)*28;return {start:dates[begin],end:dates[Math.min(begin+(begin===0?4:begin===452?5:28)-1,456)]};}\n function swapBundle(rows,first,compensation=null){\n  const {date,a,b}=first,window=swapWindow(date);\n  if(!Number.isInteger(a)||!Number.isInteger(b)||a<0||a>7||b<0||b>7||a===b)throw Error('Chọn hai nhân viên khác nhau.');\n  const i=diff(date,START),sa=rows[i].shifts[a],sb=rows[i].shifts[b];\n  if(sa===sb)throw Error('Hai nhân viên đang cùng ca, không cần đổi.');\n  const indices=[i];\n  if(compensation){\n   if(compensation===date)throw Error('Hai lần đổi phải ở hai ngày khác nhau.');\n   if(!dates.includes(compensation)||compensation<window.start||compensation>window.end)throw Error('Ngày đổi bù phải nằm trong cùng chu kỳ 4 tuần (hoặc cùng phần ngày lẻ).');\n   const j=diff(compensation,START),ta=rows[j].shifts[a],tb=rows[j].shifts[b];\n   if((sa<2)===(sb<2)||(ta<2)!==(sb<2)||(tb<2)!==(sa<2))throw Error('Lần đổi bù phải đổi ca ngày ↔ ca đêm theo chiều ngược lại cho cùng hai người.');\n   indices.push(j);\n  }\n  return rows.map((r,k)=>{if(!indices.includes(k))return r;const shifts=r.shifts.slice();[shifts[a],shifts[b]]=[shifts[b],shifts[a]];return {date:r.date,shifts};});\n }\n function compensationDates(rows,first){const window=swapWindow(first.date);return rows.filter(r=>r.date>=window.start&&r.date<=window.end&&r.date!==first.date).filter(r=>{try{return !validate(swapBundle(rows,first,r.date)).length;}catch{return false;}}).map(r=>r.date);}\n const api={START,END,CYCLE_START,SHIFTS,CYCLE,dates,add,diff,create,validate,stats,phasesFor,swapWindow,swapBundle,compensationDates};\n if(typeof module!=='undefined'&&module.exports)module.exports=api;else root.PageScheduler=api;\n})(typeof globalThis!=='undefined'?globalThis:this);\n\n</script>\n<script>\n(async()=>{\n'use strict';\nconst S=PageScheduler, $=id=>document.getElementById(id);\nlet auth,remote,revision,saving=false,lastConfirmed;\nasync function api(url,options={}){const response=await fetch(url,{...options,headers:{'Content-Type':'application/json',...(auth?{'X-CSRF-Token':auth.csrf}:{}),...options.headers}});const data=await response.json();if(response.status===401){location.assign('/login');throw Error('Hãy đăng nhập lại.');}if(!response.ok)throw Object.assign(Error(data.error||'Không kết nối được máy chủ.'),{status:response.status});return data;}\ntry{auth=await api('/api/session');remote=await api('/api/schedule');}catch(e){$('saveStatus').textContent=e.message;return;}\nconst isAdmin=auth.role==='admin';revision=remote.revision;lastConfirmed=remote;\n$('accessRole').textContent=isAdmin?'Quản lý · Có quyền cập nhật':'Nhân viên · Chỉ xem';$('setupPanel').hidden=!isAdmin;$('adminPanel').hidden=!isAdmin;$('import').hidden=!isAdmin;\n$('logout').onclick=async()=>{try{await api('/api/logout',{method:'POST',body:'{}'});location.assign('/login');}catch(e){toast(e.message);}};\nlet names=remote.names,rows=remote.rows,selection=S.CYCLE_START,swapping=null;\nconst fmt=d=>d.split('-').reverse().join('/'), safe=s=>String(s).replace(/[&<>\"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#39;'}[c]));\nconst weekdays=['CN','Thứ 2','Thứ 3','Thứ 4','Thứ 5','Thứ 6','Thứ 7'];\nfunction toast(msg){$('toast').textContent=msg;$('toast').style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('toast').style.display='none',6000);}\nfunction payload(){return {version:3,start:S.START,end:S.END,names,rows};}\nfunction validNames(n){return Array.isArray(n)&&n.length===8&&n.every(x=>typeof x==='string'&&x.trim().length>0&&x.trim().length<=40)&&new Set(n.map(x=>x.trim().toLocaleLowerCase())).size===8;}\nfunction confirmRemote(data){names=data.names;rows=data.rows;revision=data.revision;lastConfirmed=data;$('saveStatus').textContent='Bản '+revision+' · Cập nhật '+new Date(data.updatedAt).toLocaleString('vi-VN');}\nasync function save(action='Cập nhật lịch'){\n if(!isAdmin){toast('Nhân viên chỉ được xem lịch.');return false;}if(saving){toast('Đang lưu thay đổi trước đó.');return false;}saving=true;$('saveStatus').textContent='Đang lưu lên máy chủ…';\n try{const data=await api('/api/schedule',{method:'PUT',body:JSON.stringify({...payload(),revision,action})});confirmRemote(data);return true;}\n catch(e){try{confirmRemote(await api('/api/schedule'));}catch{confirmRemote(lastConfirmed);}render();settings();toast(e.message);return false;}\n finally{saving=false;}\n}\nconfirmRemote(remote);\nfunction weekDates(){const wd=new Date(selection+'T00:00:00Z').getUTCDay();const monday=S.add(selection,-((wd+6)%7));return Array.from({length:7},(_,i)=>S.add(monday,i));}\nfunction scopeRows(){const scope=$('scope').value;if(scope==='all')return rows;if(scope==='month')return rows.filter(r=>r.date.slice(0,7)===selection.slice(0,7));if(scope==='week'){const ds=weekDates();return rows.filter(r=>ds.includes(r.date));}if(selection<S.CYCLE_START)return rows.slice(0,4);const start=4+Math.floor(S.diff(selection,S.CYCLE_START)/28)*28;return rows.slice(start,start+28);}\nfunction statsRender(){const selected=scopeRows(),st=S.stats(selected),hs=st.map(x=>x.hours);$('stats').innerHTML='<thead><tr><th>Nhân viên</th><th>Số ca</th><th>Ca 1 / 2 / 3 / 4</th><th>Giờ công</th></tr></thead><tbody>'+st.map((x,e)=>'<tr><td class=\"name\">'+safe(names[e])+'</td><td>'+x.days+'</td><td>'+x.counts.join(' / ')+'</td><td class=\"hours\">'+x.hours+' h</td></tr>').join('')+'</tbody>';$('statNote').textContent=fmt(selected[0].date)+' – '+fmt(selected.at(-1).date)+' · Chênh lệch cao nhất: '+(Math.max(...hs)-Math.min(...hs))+' giờ.';}\nfunction render(){\n const ds=weekDates();$('date').value=selection;$('weekTitle').textContent='Tuần '+fmt(ds[0])+' – '+fmt(ds[6]);\n $('prev').disabled=ds[0]<=S.START;$('next').disabled=ds[6]>=S.END;\n const weekly=rows.filter(r=>ds.includes(r.date)),st=S.stats(weekly);\n $('weekTable').innerHTML='<thead><tr><th>NHÂN VIÊN</th>'+ds.map(d=>'<th>'+weekdays[new Date(d+'T00:00:00Z').getUTCDay()]+'<br>'+fmt(d).slice(0,5)+'</th>').join('')+'<th>GIỜ / TUẦN</th></tr></thead><tbody>'+names.map((n,e)=>'<tr><td class=\"name\">'+safe(n)+'</td>'+ds.map(d=>{if(d<S.START||d>S.END)return '<td style=\"color:#a9b5af\">Ngoài kỳ</td>';const s=rows[S.diff(d,S.START)].shifts[e];return '<td><button class=\"shift s'+s+'\" data-day=\"'+d+'\" data-person=\"'+e+'\" title=\"'+S.SHIFTS[s].time+'\">'+S.SHIFTS[s].name+' · '+S.SHIFTS[s].hours+'h</button></td>';}).join('')+'<td class=\"hours\">'+st[e].hours+' h</td></tr>').join('')+'</tbody>';\n $('weekFoot').textContent=weekly.length+' ngày trong kỳ · '+weekly.length+' ca/người · '+weekly.length*48+' giờ công toàn đội. '+(weekly.length<7?'Tuần đầu/cuối chỉ tính ngày nằm trong kỳ.':'');\n const all=S.stats(rows),hs=all.map(x=>x.hours);$('gapMetric').innerHTML=(Math.max(...hs)-Math.min(...hs))+' <span>giờ giữa các nhân viên</span>';$('totalRange').textContent=Math.min(...hs).toLocaleString('vi-VN')+' – '+Math.max(...hs).toLocaleString('vi-VN')+' giờ / người';\n let min=Infinity,max=-Infinity;for(let i=1;i<rows.length;i++)for(let e=0;e<8;e++){const r=24+S.SHIFTS[rows[i].shifts[e]].start-S.SHIFTS[rows[i-1].shifts[e]].end;min=Math.min(min,r);max=Math.max(max,r);}$('restMetric').innerHTML=min+'–'+max+' <span>giờ</span>';\n const errs=S.validate(rows);$('health').textContent=errs.length?'Lịch cần sửa':'✓ Đủ người · Nghỉ hợp lệ · Cân bằng 4 tuần';statsRender();\n}\nfunction settings(){ $('settings').innerHTML=names.map((n,e)=>'<div class=\"person\"><input aria-label=\"Tên nhân viên '+(e+1)+'\" maxlength=\"40\" value=\"'+safe(n)+'\" id=\"name'+e+'\"><select aria-label=\"Ca khởi đầu nhân viên '+(e+1)+'\" id=\"choice'+e+'\">'+S.SHIFTS.map(s=>'<option value=\"'+s.id+'\" '+(rows[0].shifts[e]===s.id?'selected':'')+'>'+s.name+'</option>').join('')+'</select></div>').join('');}\nfunction readNames(){const n=names.map((_,e)=>$('name'+e).value.trim());if(!validNames(n))throw Error('Nhập đủ 8 tên khác nhau, mỗi tên từ 1 đến 40 ký tự.');return n;}\nfunction download(name,content,type){const a=document.createElement('a'),url=URL.createObjectURL(new Blob([content],{type}));a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),2000);}\nfunction firstSwap(){return {date:swapping.date,a:swapping.e,b:Number($('partner').value)};}\nfunction swapCandidate(){const paired=$('swapMode').value==='paired';if(paired&&!$('compensation').value)throw Error('Không có ngày đổi bù hợp lệ cho cặp nhân viên này. Hãy chọn người khác hoặc ngày đổi đầu tiên khác.');return S.swapBundle(rows,firstSwap(),paired?$('compensation').value:null);}\nfunction configureSwap(autoMode=false){\n const first=firstSwap(),r=rows[S.diff(first.date,S.START)],cross=(r.shifts[first.a]<2)!==(r.shifts[first.b]<2);\n if(autoMode)$('swapMode').value=cross?'paired':'single';\n const paired=$('swapMode').value==='paired';$('compensationFields').hidden=!paired;\n if(paired){const old=$('compensation').value,ds=S.compensationDates(rows,first),window=S.swapWindow(first.date);$('compensation').innerHTML=ds.length?ds.map(d=>{const row=rows[S.diff(d,S.START)];return '<option value=\"'+d+'\">'+fmt(d)+' · '+safe(names[first.a])+': '+S.SHIFTS[row.shifts[first.a]].name+' ↔ '+safe(names[first.b])+': '+S.SHIFTS[row.shifts[first.b]].name+'</option>';}).join(''):'<option value=\"\">Không có ngày đổi bù hợp lệ</option>';$('compensation').value=ds.includes(old)?old:(ds[0]||'');$('compensationNote').textContent='Chỉ liệt kê ngày đổi bù đã kiểm tra khoảng nghỉ và cân bằng. Phạm vi: '+fmt(window.start)+' – '+fmt(window.end)+'.';}\n preview();\n}\nfunction preview(){\n try{const candidate=swapCandidate(),errors=S.validate(candidate),first=firstSwap(),paired=$('swapMode').value==='paired';$('swapError').textContent=errors.length?'Không thể đổi: '+errors.slice(0,2).join(' ').replace(/nhân viên (\\d+)/g,(_,n)=>'nhân viên '+names[Number(n)-1]):'';$('applySwap').disabled=!!errors.length||saving;\n const dates=paired?[first.date,$('compensation').value]:[first.date],changes=dates.map(d=>{const i=S.diff(d,S.START);return fmt(d)+': '+names[first.a]+' '+S.SHIFTS[rows[i].shifts[first.a]].name+' → '+S.SHIFTS[candidate[i].shifts[first.a]].name+'; '+names[first.b]+' '+S.SHIFTS[rows[i].shifts[first.b]].name+' → '+S.SHIFTS[candidate[i].shifts[first.b]].name;});\n const hs=S.stats(candidate).map(s=>s.hours);$('swapPreview').textContent=changes.join('\\n')+'\\nChênh lệch giờ toàn kỳ sau đổi: '+(Math.max(...hs)-Math.min(...hs))+' giờ.';$('applySwap').textContent=paired?'Áp dụng cả hai lần':'Áp dụng đổi ca';\n }catch(e){$('swapError').textContent=e.message;$('applySwap').disabled=true;$('swapPreview').textContent='Chưa thay đổi lịch.';}\n}\n$('weekTable').onclick=ev=>{if(!isAdmin){toast('Bạn đang xem lịch. Chỉ người quản lý được đổi ca.');return;}if(saving)return;const b=ev.target.closest('[data-day]');if(!b)return;swapping={date:b.dataset.day,e:Number(b.dataset.person)};const r=rows[S.diff(swapping.date,S.START)],s=r.shifts[swapping.e];$('swapTitle').textContent='Đổi ca · '+fmt(swapping.date);$('swapInfo').textContent=names[swapping.e]+' đang làm '+S.SHIFTS[s].name+' ('+S.SHIFTS[s].time+').';const partners=names.map((n,e)=>e!==swapping.e&&r.shifts[e]!==s?e:null).filter(e=>e!==null);$('partner').innerHTML=partners.map(e=>'<option value=\"'+e+'\">'+safe(names[e])+' · '+S.SHIFTS[r.shifts[e]].name+'</option>').join('');$('partner').value=String(partners[0]);configureSwap(true);$('swapDialog').showModal();};\n$('partner').onchange=()=>configureSwap(true);$('swapMode').onchange=()=>configureSwap();$('compensation').onchange=preview;\n$('cancelSwap').onclick=()=>$('swapDialog').close();$('applySwap').onclick=async()=>{if(!isAdmin||saving)return;try{const candidate=swapCandidate(),errors=S.validate(candidate);if(errors.length){preview();return;}const paired=$('swapMode').value==='paired';rows=candidate;if(!await save(paired?'Đổi hai lần bù nhau: '+swapping.date+' và '+$('compensation').value:'Đổi ca ngày '+swapping.date))return;render();settings();$('swapDialog').close();toast(paired?'Đã lưu cả hai lần đổi bù. Khoảng nghỉ và cân bằng 4 tuần hợp lệ.':'Đã đổi ca và kiểm tra toàn kỳ.');}catch(e){$('swapError').textContent=e.message;$('applySwap').disabled=true;}};\n$('date').onchange=()=>{if($('date').value<S.START||$('date').value>S.END){$('date').value=selection;toast('Chọn ngày trong khoảng 01/10/2026 – 31/12/2027.');return;}selection=$('date').value;render();};\n$('prev').onclick=()=>{selection=S.add(selection,-7);if(selection<S.START)selection=S.START;render();};$('next').onclick=()=>{selection=S.add(selection,7);if(selection>S.END)selection=S.END;render();};$('scope').onchange=statsRender;$('print').onclick=()=>window.print();\n$('rename').onclick=async()=>{if(!isAdmin||saving)return;try{names=readNames();if(!await save('Cập nhật tên nhân viên'))return;render();toast('Đã lưu tên nhân viên.');}catch(e){toast(e.message);}};\n$('regenerate').onclick=()=>{if(!isAdmin||saving)return;try{readNames();S.phasesFor(names.map((_,e)=>$('choice'+e).value));$('confirmDialog').showModal();}catch(e){toast(e.message);}};$('cancelReset').onclick=()=>$('confirmDialog').close();$('confirmReset').onclick=async()=>{if(!isAdmin||saving)return;try{const newNames=readNames(),candidate=S.create(S.phasesFor(names.map((_,e)=>$('choice'+e).value)));if(S.validate(candidate).length)throw Error('Lịch không hợp lệ.');names=newNames;rows=candidate;if(!await save('Tạo lại lịch theo ca khởi đầu'))return;render();settings();$('confirmDialog').close();toast('Đã tạo lịch đủ 457 ngày.');}catch(e){toast(e.message);}};\n$('backup').onclick=()=>download('pageops-backup.json',JSON.stringify(payload(),null,2),'application/json');$('import').onclick=()=>{if(isAdmin&&!saving)$('file').click();};$('file').onchange=async()=>{if(!isAdmin||saving)return;const f=$('file').files[0];if(!f)return;try{if(f.size>2000000)throw Error('Bản sao quá lớn (tối đa 2 MB).');const data=JSON.parse(await f.text());if(data.version!==3||!validNames(data.names))throw Error('Sai định dạng, phiên bản hoặc tên nhân viên. Cần JSON phiên bản 3 của lịch tuần thứ Hai.');const errors=S.validate(data.rows);if(errors.length)throw Error(errors.slice(0,2).join(' '));if(!window.confirm('Thay lịch hiện tại bằng bản sao đã kiểm tra?'))return;names=data.names.map(n=>n.trim());rows=data.rows.map(r=>({date:r.date,shifts:r.shifts.slice()}));if(!await save('Nhập bản sao JSON'))return;render();settings();toast('Đã nhập và kiểm tra lịch.');}catch(e){toast('Không nhập được: '+e.message);}$('file').value='';};\n$('csv').onclick=()=>{const quote=v=>'\"'+String(v).replace(/\"/g,'\"\"')+'\"';let out=[['Ngày','Nhân viên','Ca','Bắt đầu','Kết thúc','Giờ công','Nghỉ trước ca (giờ)']];rows.forEach((r,i)=>r.shifts.forEach((s,e)=>{const shift=S.SHIFTS[s],rest=i?24+shift.start-S.SHIFTS[rows[i-1].shifts[e]].end:'';const time=h=>String(h).padStart(2,'0')+':00';out.push([r.date,names[e],shift.name,r.date+' '+time(shift.start),(shift.end===24?S.add(r.date,1):r.date)+' '+time(shift.end%24),shift.hours,rest]);}));download('lich-truc-2026-10_2027-12.csv','\\uFEFF'+out.map(r=>r.map(quote).join(',')).join('\\r\\n'),'text/csv;charset=utf-8');toast('Đã xuất toàn kỳ: 3.656 lượt ca.');};\n$('legend').innerHTML=S.SHIFTS.map(s=>'<span><i class=\"dot s'+s.id+'\"></i>'+s.name+' · '+s.time+'</span>').join('');settings();render();\n\nasync function passwordProof(password,role){\n const response=await fetch('/api/login-config');const config=await response.json();if(!response.ok||!config.salts?.[role]||config.iterations!==600000)throw Error('Web chưa được khởi tạo mật khẩu.');\n const key=await crypto.subtle.importKey('raw',new TextEncoder().encode(password),'PBKDF2',false,['deriveBits']);const bits=await crypto.subtle.deriveBits({name:'PBKDF2',hash:'SHA-256',salt:new TextEncoder().encode(config.salts[role]),iterations:600000},key,256);return Array.from(new Uint8Array(bits),v=>v.toString(16).padStart(2,'0')).join('');\n}\nasync function refreshHistory(){if(!isAdmin)return;try{const entries=await api('/api/history');$('historyTable').innerHTML='<thead><tr><th>Bản</th><th>Thay đổi</th><th>Thời gian</th></tr></thead><tbody>'+entries.map(e=>'<tr><td>'+e.revision+'</td><td>'+safe(e.action)+'</td><td>'+new Date(e.updated_at).toLocaleString('vi-VN')+'</td></tr>').join('')+'</tbody>';}catch{}}\n$('passwordForm').onsubmit=async ev=>{ev.preventDefault();if(!isAdmin)return;try{const role=$('passwordRole').value,password=$('newPassword').value;if(password.length<(role==='admin'?12:8)||password.length>200)throw Error('Mật khẩu mới chưa đủ dài.');if(role==='viewer'&&password===$('currentPassword').value)throw Error('Mật khẩu nhân viên và quản lý phải khác nhau.');await api('/api/password',{method:'POST',body:JSON.stringify({role,currentProof:await passwordProof($('currentPassword').value,'admin'),newProof:await passwordProof(password,role)})});$('currentPassword').value='';$('newPassword').value='';toast('Đã đổi mật khẩu. Các phiên khác của vai trò này đã đăng xuất.');}catch(e){toast(e.message);}};\nawait refreshHistory();\nsetInterval(async()=>{if(saving||$('swapDialog').open||$('confirmDialog').open||document.hidden)return;try{const data=await api('/api/schedule');if(data.revision!==revision){confirmRemote(data);render();settings();toast('Đã nhận lịch mới từ người quản lý.');}else $('saveStatus').textContent='Bản '+revision+' · Đã đồng bộ '+new Date().toLocaleTimeString('vi-VN');await refreshHistory();}catch(e){$('saveStatus').textContent='Chưa kết nối được máy chủ; đang hiển thị bản '+revision+'.';}},15000);\n})().catch(e=>{document.getElementById('saveStatus').textContent=e.message;});\n</script></body></html>\n";
const LOGIN_HTML="<!doctype html><html lang=\"vi\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>Đăng nhập · PageOps</title><style>*{box-sizing:border-box}body{margin:0;background:#edf3ef;color:#16352d;font:16px/1.5 'Segoe UI',Arial;min-height:100vh;display:grid;place-items:center;padding:20px}.card{background:white;border:1px solid #d9e6dd;border-radius:20px;max-width:440px;width:100%;padding:36px;box-shadow:0 18px 60px #16352d0d}h1{font-size:32px;margin:0}h1 span{color:#14785d}p{color:#657b73}label{display:block;margin-top:20px;font-weight:600}input,select,button{font:inherit;width:100%;padding:13px;border:1px solid #ccdcd2;border-radius:9px;margin-top:8px;color:#16352d;background:white}button{background:#14785d;color:white;cursor:pointer;margin-top:25px;border:0}button:disabled{opacity:.6}#error{color:#a43d2c;font-size:14px}small{color:#657b73}</style></head><body><main class=\"card\"><h1>Page<span>Ops</span></h1><p>Lịch trực chung của đội ngũ.</p><form id=\"loginForm\"><label for=\"role\">Bạn truy cập với vai trò</label><select id=\"role\"><option value=\"viewer\">Nhân viên · Xem lịch</option><option value=\"admin\">Quản lý · Cập nhật lịch</option></select><label for=\"password\">Mật khẩu</label><input id=\"password\" type=\"password\" required maxlength=\"200\" autocomplete=\"current-password\"><p id=\"error\" role=\"alert\"></p><button id=\"submit\" type=\"submit\">Đăng nhập</button></form><p><small>Nhân viên dùng mật khẩu xem lịch do người quản lý cung cấp.</small></p></main><script>async function passwordProof(password,role){\n const response=await fetch('/api/login-config');const config=await response.json();if(!response.ok||!config.salts?.[role]||config.iterations!==600000)throw Error('Web chưa được khởi tạo mật khẩu.');\n const key=await crypto.subtle.importKey('raw',new TextEncoder().encode(password),'PBKDF2',false,['deriveBits']);const bits=await crypto.subtle.deriveBits({name:'PBKDF2',hash:'SHA-256',salt:new TextEncoder().encode(config.salts[role]),iterations:600000},key,256);return Array.from(new Uint8Array(bits),v=>v.toString(16).padStart(2,'0')).join('');\n}\ndocument.getElementById('loginForm').onsubmit=async ev=>{ev.preventDefault();const button=document.getElementById('submit');button.disabled=true;document.getElementById('error').textContent='';try{const response=await fetch('/api/login',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({role:document.getElementById('role').value,proof:await passwordProof(document.getElementById('password').value,document.getElementById('role').value)})});const data=await response.json();if(!response.ok)throw Error(data.error||'Chưa đăng nhập được.');location.assign('/');}catch(e){document.getElementById('error').textContent=e.message;button.disabled=false;}};</script></body></html>\n";

const SETUP_HTML="<!doctype html><html lang=\"vi\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>Đăng nhập · PageOps</title><style>*{box-sizing:border-box}body{margin:0;background:#edf3ef;color:#16352d;font:16px/1.5 'Segoe UI',Arial;min-height:100vh;display:grid;place-items:center;padding:20px}.card{background:white;border:1px solid #d9e6dd;border-radius:20px;max-width:440px;width:100%;padding:36px;box-shadow:0 18px 60px #16352d0d}h1{font-size:32px;margin:0}h1 span{color:#14785d}p{color:#657b73}label{display:block;margin-top:20px;font-weight:600}input,select,button{font:inherit;width:100%;padding:13px;border:1px solid #ccdcd2;border-radius:9px;margin-top:8px;color:#16352d;background:white}button{background:#14785d;color:white;cursor:pointer;margin-top:25px;border:0}button:disabled{opacity:.6}#error{color:#a43d2c;font-size:14px}small{color:#657b73}</style></head><body><main class=\"card\"><h1>Page<span>Ops</span></h1><p>Thiết lập lần đầu cho web lịch trực.</p><form id=\"setupForm\"><label for=\"setupKey\">Khóa cài đặt riêng</label><input id=\"setupKey\" type=\"password\" required autocomplete=\"off\"><label for=\"adminPassword\">Mật khẩu quản lý (ít nhất 12 ký tự)</label><input id=\"adminPassword\" type=\"password\" minlength=\"12\" maxlength=\"200\" required autocomplete=\"new-password\"><label for=\"viewerPassword\">Mật khẩu nhân viên (ít nhất 8 ký tự)</label><input id=\"viewerPassword\" type=\"password\" minlength=\"8\" maxlength=\"200\" required autocomplete=\"new-password\"><p id=\"error\" role=\"alert\"></p><button id=\"submit\">Tạo mật khẩu và lịch</button></form><p><small>Chỉ chia sẻ mật khẩu nhân viên. Màn hình này tự khóa sau khi thiết lập thành công.</small></p></main><script>async function passwordProof(password,role){\n const response=await fetch('/api/setup-config');const config=await response.json();if(!response.ok||!config.salts?.[role]||config.iterations!==600000)throw Error('Web chưa được khởi tạo mật khẩu.');\n const key=await crypto.subtle.importKey('raw',new TextEncoder().encode(password),'PBKDF2',false,['deriveBits']);const bits=await crypto.subtle.deriveBits({name:'PBKDF2',hash:'SHA-256',salt:new TextEncoder().encode(config.salts[role]),iterations:600000},key,256);return Array.from(new Uint8Array(bits),v=>v.toString(16).padStart(2,'0')).join('');\n}\ndocument.getElementById('setupForm').onsubmit=async ev=>{ev.preventDefault();const button=document.getElementById('submit');button.disabled=true;try{const admin=document.getElementById('adminPassword').value,viewer=document.getElementById('viewerPassword').value;if(admin.length<12||viewer.length<8||admin.length>200||viewer.length>200||admin===viewer)throw Error('Hai mật khẩu cần khác nhau và đủ độ dài.');const proofs=await Promise.all([passwordProof(admin,'admin'),passwordProof(viewer,'viewer')]);const response=await fetch('/api/setup',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({key:document.getElementById('setupKey').value,adminProof:proofs[0],viewerProof:proofs[1]})});const result=await response.json();if(!response.ok)throw Error(result.error);document.getElementById('setupKey').value='';document.getElementById('adminPassword').value='';document.getElementById('viewerPassword').value='';location.assign('/login');}catch(e){document.getElementById('error').textContent=e.message;button.disabled=false;}};</script></body></html>";
const SCHEMA_STATEMENTS=["CREATE TABLE IF NOT EXISTS credentials(role TEXT PRIMARY KEY,salt TEXT NOT NULL,password_hash TEXT NOT NULL);", "CREATE TABLE IF NOT EXISTS sessions(token_hash TEXT PRIMARY KEY,role TEXT NOT NULL,csrf TEXT NOT NULL,expires INTEGER NOT NULL);", "CREATE TABLE IF NOT EXISTS attempts(key TEXT PRIMARY KEY,count INTEGER NOT NULL,until INTEGER NOT NULL);", "CREATE TABLE IF NOT EXISTS schedule(id INTEGER PRIMARY KEY CHECK(id=1),revision INTEGER NOT NULL,data TEXT NOT NULL,updated_at TEXT NOT NULL,action TEXT NOT NULL);", "CREATE TABLE IF NOT EXISTS history(id INTEGER PRIMARY KEY AUTOINCREMENT,revision INTEGER NOT NULL,data TEXT NOT NULL,action TEXT NOT NULL,updated_at TEXT NOT NULL);", "CREATE INDEX IF NOT EXISTS sessions_expiry ON sessions(expires);", "CREATE TRIGGER IF NOT EXISTS schedule_history AFTER UPDATE ON schedule BEGIN\n INSERT INTO history(revision,data,action,updated_at) VALUES(new.revision,new.data,new.action,new.updated_at);\n DELETE FROM history WHERE id NOT IN (SELECT id FROM history ORDER BY id DESC LIMIT 30);\nEND;"];
